"""Leaving lockfiles and generated files out of a review, and splitting a
large diff into parts without breaking line numbers."""

from revu.context.chunks import split_for_review
from revu.context.diff import block_path, parse_diff, split_file_blocks
from revu.context.noise import drop_noise, skip_reason


def _file(path: str, *hunks: tuple[int, list[str]]) -> str:
    out = f"diff --git a/{path} b/{path}\nindex 111..222 100644\n--- a/{path}\n+++ b/{path}\n"
    for start, lines in hunks:
        out += f"@@ -{start},0 +{start},{len(lines)} @@\n" + "".join(f"+{x}\n" for x in lines)
    return out


APP = _file("src/app.py", (10, ["def f(x):", "    return 1 / x"]))
LOCK = _file("web/package-lock.json", (1, ['{"lockfileVersion": 3}'] * 50))
MINIFIED = _file("static/app.min.js", (1, ["var a=1;"]))
VENDORED = _file("vendor/github.com/x/y.go", (1, ["package y"]))
GENERATED = _file(
    "api/types.go", (1, ["// Code generated by protoc-gen-go. DO NOT EDIT.", "package api"])
)
BINARY = (
    "diff --git a/logo.png b/logo.png\nindex 1..2 100644\n"
    "Binary files a/logo.png and b/logo.png differ\n"
)


def test_blocks_are_one_per_file_and_join_back_to_the_original() -> None:
    diff = APP + BINARY + LOCK

    blocks = split_file_blocks(diff)

    assert "".join(blocks) == diff
    assert [block_path(b) for b in blocks] == ["src/app.py", "logo.png", "web/package-lock.json"]


def test_a_plain_unified_diff_without_git_headers_is_split_too() -> None:
    diff = (
        "--- a/x.py\n+++ b/x.py\n@@ -1 +1 @@\n-a\n+b\n--- a/y.py\n+++ b/y.py\n@@ -1 +1 @@\n-c\n+d\n"
    )

    assert [block_path(b) for b in split_file_blocks(diff)] == ["x.py", "y.py"]


def test_lockfiles_minified_vendored_and_generated_files_are_left_out() -> None:
    filtered = drop_noise(APP + LOCK + MINIFIED + VENDORED + GENERATED + BINARY)

    assert filtered.skipped == [
        "web/package-lock.json",
        "static/app.min.js",
        "vendor/github.com/x/y.go",
        "api/types.go",
    ]
    assert filtered.diff == APP + BINARY  # what stays is byte-for-byte the same
    assert parse_diff(filtered.diff)[0].hunks[0].new_start == 10


def test_a_generated_marker_only_counts_near_the_top_of_the_file() -> None:
    late = _file("src/gen.py", (50, ["# This file was automatically generated, see notes"]))

    assert skip_reason("src/gen.py", late) is None
    assert skip_reason("src/lockfile.py") is None  # a name, not a lockfile
    assert skip_reason("Cargo.lock") == "lockfile"


def test_a_small_diff_is_one_part_and_an_empty_one_none() -> None:
    assert split_for_review(APP, max_chars=10_000) == [APP]
    assert split_for_review("", max_chars=10_000) == []


def test_files_are_packed_into_parts_under_the_limit() -> None:
    files = [_file(f"src/m{i}.py", (1, [f"x = {i}"] * 5)) for i in range(6)]
    diff = "".join(files)
    limit = len(files[0]) * 2 + 1

    parts = split_for_review(diff, max_chars=limit)

    assert len(parts) == 3
    assert all(len(p) <= limit for p in parts)
    assert "".join(parts) == diff


def test_a_file_larger_than_the_limit_is_cut_between_hunks_keeping_its_header() -> None:
    big = _file("src/big.py", *[(start, [f"line {start}"] * 20) for start in (1, 100, 200, 300)])
    hunk_size = len(big) // 4

    parts = split_for_review(big, max_chars=hunk_size * 2)

    assert len(parts) >= 2
    starts = []
    for part in parts:
        (file_diff,) = parse_diff(part)
        assert file_diff.file_path == "src/big.py"
        starts += [h.new_start for h in file_diff.hunks]
    assert starts == [1, 100, 200, 300]  # every hunk once, line numbers intact
